<script>
  import {onMount,onDestroy} from 'svelte';import {client,createLoader,tablePath,isAbort} from '../lib/api.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';
  export let table;export let lang='vi';const resource=createLoader();let endpoint='ask',method='POST',language='curl',topK=3,mode='auto',question='',keyId='',secret='',busy=false,error='',copied='',timer,alive=true;
  $: t=(vi,en)=>lang==='en'?en:vi;
  $: base=location.origin+tablePath(table.slug);
  $: example=question||t('Tìm sản phẩm phù hợp','Find a matching product');
  $: body=endpoint==='ask'?{text:example,mode,top_k:Number(topK)}:{rows:[Object.fromEntries((table.columns.length?table.columns:['name']).map(c=>[c,c==='name'?'Sản phẩm mẫu':'...']))]};
  $: url=base+(endpoint==='ask'?'/ask':'/rows')+(endpoint==='ask'&&method==='GET'?`?text=${encodeURIComponent(example)}&mode=${mode}&top_k=${topK}`:'');
  $: verb=endpoint==='rows'?'PUT':method;
  $: token=secret||'YOUR_TABLE_KEY';
  $: snippet=language==='curl'?`curl -X ${verb} '${url}' \\\n  -H 'X-Table-Key: ${token}'${verb==='GET'?'':` \\\n  -H 'Content-Type: application/json' \\\n  -d '${JSON.stringify(body,null,2).replace(/'/g,"'\\''")}'`}`:
    language==='python'?`import requests\n\nresponse = requests.${verb.toLowerCase()}(\n    ${JSON.stringify(url)},\n    headers={"X-Table-Key": ${JSON.stringify(token)}},\n${verb==='GET'?'':`    json=${JSON.stringify(body,null,4)},\n`}    timeout=30,\n)\nresponse.raise_for_status()\nprint(response.json())`:
    `const response = await fetch(${JSON.stringify(url)}, {\n  method: ${JSON.stringify(verb)},\n  headers: {\n    "X-Table-Key": ${JSON.stringify(token)}${verb==='GET'?'':',\n    "Content-Type": "application/json"'}\n  }${verb==='GET'?'':`,\n  body: JSON.stringify(${JSON.stringify(body,null,2)})`}\n});\nif (!response.ok) throw new Error(\`HTTP \${response.status}\`);\nconst data = await response.json();`;
  function clear(){secret='';clearTimeout(timer);}
  async function reveal(){if(busy||!keyId)return;busy=true;error='';try{const result=await client.request(`${tablePath(table.slug)}/keys/${keyId}/reveal`,{method:'POST'});if(alive){secret=result.key;timer=setTimeout(clear,30000);}}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy=false;}}
  async function copy(value,label){try{await navigator.clipboard.writeText(value);copied=label;setTimeout(()=>{if(alive)copied='';},1800);}catch{error=t('Không sao chép được. Hãy chọn nội dung để sao chép thủ công.','Could not copy. Select the text to copy manually.');}}
  const hide=()=>{if(document.hidden)clear();};
  onMount(()=>{resource.load(signal=>client.request(`${tablePath(table.slug)}/keys`,{signal}));document.addEventListener('visibilitychange',hide);window.addEventListener('pagehide',clear);});onDestroy(()=>{alive=false;clear();resource.dispose();document.removeEventListener('visibilitychange',hide);window.removeEventListener('pagehide',clear);});
</script>
<div class="grid xl:grid-cols-[340px_1fr] gap-5">
  <section class="panel"><h2>{t('Cấu hình request','Request configuration')}</h2><div class="space-y-5 mt-5"><label class="field"><span>{t('Chức năng','Endpoint')}</span><select bind:value={endpoint}><option value="ask">{t('Tìm kiếm dữ liệu','Search data')}</option><option value="rows">{t('Thêm / cập nhật dòng','Add / update rows')}</option></select></label>{#if endpoint==='ask'}<label class="field"><span>{t('Phương thức','Method')}</span><select bind:value={method}><option>POST</option><option>GET</option></select></label><label class="field"><span>{t('Câu hỏi mẫu','Example question')}</span><input bind:value={question} placeholder={t('Nhập câu hỏi…','Enter a question…')}/></label><div class="grid grid-cols-2 gap-3"><label class="field"><span>{t('Chế độ','Mode')}</span><select bind:value={mode}><option value="auto">Auto</option><option value="fast">Fast</option><option value="accurate">Accurate</option></select></label><label class="field"><span>{t('Số kết quả','Results')}</span><select bind:value={topK}>{#each [1,2,3,4,5] as n}<option value={n}>{n}</option>{/each}</select></label></div>{/if}<div class="border-t border-line pt-5"><label class="field"><span>{t('Khoá API trong mã mẫu','API key in sample')}</span><select bind:value={keyId} on:change={clear}><option value="">YOUR_TABLE_KEY</option>{#each $resource.data || [] as key}<option value={key.id} disabled={!key.can_reveal||!key.active}>{key.name} · {key.prefix}…</option>{/each}</select></label><div class="flex gap-2 mt-3">{#if secret}<Button on:click={clear}>{t('Ẩn khoá khỏi mã','Hide key')}</Button>{:else}<Button {busy} disabled={!keyId} on:click={reveal}>{t('Dùng khoá trong mã','Use key in sample')}</Button>{/if}</div><p class="text-muted text-xs mt-3">{t('Khoá chỉ được đưa vào mẫu sau khi bạn chọn. Tự xoá sau 30 giây.','Keys are inserted only on request and cleared after 30 seconds.')}</p></div></div><Notice error={$resource.error || error} {lang}/></section>
  <section class="panel min-w-0"><div class="flex justify-between gap-3 items-center mb-5"><h2>{t('Mã tích hợp','Integration code')}</h2><label><span class="sr-only">{t('Ngôn ngữ lập trình','Programming language')}</span><select class="w-auto text-xs" bind:value={language}><option value="curl">cURL</option><option value="python">Python</option><option value="javascript">JavaScript</option></select></label></div><div class="flex items-center gap-3 rounded-lg border border-line px-4 py-3 mb-4 min-w-0"><span class="badge ok">{verb}</span><code class="break-all flex-1">{url}</code></div><textarea class="codeblock w-full min-h-80" readonly value={snippet} aria-label={t("Mã mẫu tích hợp","Integration code sample")}></textarea><div class="flex flex-wrap gap-2 mt-4"><Button on:click={()=>copy(snippet,'code')}><Icon name="copy" size={16}/>{copied==='code'?t('Đã sao chép','Copied'):t('Sao chép mã','Copy code')}</Button><Button on:click={()=>copy(url,'url')}>{copied==='url'?t('Đã sao chép','Copied'):t('Sao chép URL','Copy URL')}</Button></div><div class="mt-7 pt-5 border-t border-line"><h3>{t('Kết quả trả về','Response')}</h3><p class="text-muted text-sm mt-3">{t('API tìm kiếm trả về found, status, row, rows, score và request_id. API ghi dữ liệu cần khoá có quyền write.','Search returns found, status, row, rows, score and request_id. Writes require a key with write scope.')}</p><a href="/docs" target="_blank" rel="noreferrer" class="text-action inline-flex mt-3">{t('Xem tài liệu API đầy đủ','Open full API documentation')}</a></div></section>
</div>
